.card-img-top {
    width: 100%;
    height: 20vw;
    object-fit: cover;
}

@media print {
    @page {
        margin-top: 0;
        margin-bottom: 0;
    }
    body {
        padding-top: 72px;
        padding-bottom: 72px ;
    }
}
.d-none{
  display: none;
}

body {
  background:#F9F8F8;
  font-size: 14px;
  font-family: 'Poppins', sans-serif !important;
}
h1,h2,h3,h4,h5,h6,button,input,textarea{
  font-family: 'Poppins', sans-serif !important;
}
.center-screen {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  min-height: 85vh;
}

p{
  font-size: 14px;
  font-family: 'Poppins', sans-serif !important;
}
a {
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  font-family: 'Poppins', sans-serif !important;
}
a:hover {
  color: inherit;
  text-decoration: none;
  cursor: pointer;
}

.swal2-styled:focus{
  box-shadow: none !important;
}

.icon-nav{
    padding: 6px;
    transition: 0.3s;
    color: #606060;
}
.icon-nav:hover{
    transition: 0.3s;
    color: #363B64;
}
.icon-nav:active{
    border-radius: 50%;
    padding: 8px;
    transition: 0.3s;
    color: #363B64;
    background:  rgba(0, 0, 0, 0.16);
}
.icon-nav-img{
    cursor: pointer;
    border-radius: 50%;
    width: 35px ;
    height: 35px ;
    object-fit: cover;
}
.icon-nav-img-lg{
    border-radius: 50%;
    width: 85px ;
    height: 85px ;
    object-fit: cover;
}

.side-nav-open {
    padding-top: 70px;
    height: 100%;
    width: 240px;
    position: fixed;
    top: 0;
    left: 0;
    overflow-x: hidden;
    transition: 0.3s;
    background-color: #ffffff;
    border-right: 1px solid rgba(0,0,0,.075);
    scrollbar-color: #CCCCCC #F5F5F5;
    scrollbar-width: thin;
}
.side-nav-close {
    padding-top: 70px;
    height: 100%;
    width: 0;
    position: fixed;
    top: 0;
    left: 0;
    overflow-x: hidden;
    transition: 0.3s;
    background-color: #ffffff;
    border-right: 1px solid rgba(0,0,0,.075);
    scrollbar-color: #CCCCCC #F5F5F5;
    scrollbar-width: thin;
}
.side-nav-open::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}
.side-nav-open::-webkit-scrollbar-track-piece  {
    background-color: #F5F5F5;
}
.side-nav-open::-webkit-scrollbar-thumb:vertical {
    height: 30px;
    border-radius: 4px;
    background: #CCCCCC;
}
.side-nav-close::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}
.side-nav-close::-webkit-scrollbar-track-piece  {
    background-color: #F5F5F5;
}
.side-nav-close::-webkit-scrollbar-thumb:vertical {
    height: 30px;
    border-radius: 4px;
    background: #CCCCCC;
}




.content {
    transition: 0.3s;
    margin-top: 80px;
    margin-left: 240px;
}
.content-expand {
    margin-top: 80px;
    transition: 0.3s;
    margin-left: 0;
}

.nav-logo-sm{
    width: auto;
    height: 25px;
}

.nav-logo {
    width: auto;
    height: 30px;
}


.side-bar-item{
    display: inline-block;
    padding: 15px 10px 15px 20px;
    width: 100% !important;
}
.side-bar-item:hover{
    border-left: 4px solid #CB0C9F;
    transition: 0.2s;
    background-color: #F3D9EC;
}
.side-bar-item:hover .side-bar-item-icon {
    color: #363B64;
}
.side-bar-item:hover .side-bar-item-caption {
    color: #363B64;
}
.side-bar-item-active{
    border-left: 4px solid #CB0C9F;
    background-color:#F3D9EC;
}
.side-bar-item-icon{
    font-size: 18px;
    margin-left: 10px;
    margin-right: 10px;
    font-weight: 500;
    color: #363B64;
}
.side-bar-item-caption{
    font-family: 'Poppins', sans-serif ;
    font-size: 13px;
    margin-left: 5px;
    font-weight: 500;
    color: #363B64;
}


